PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users(uid TEXT PRIMARY KEY,handle TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,avatar TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'online',last_seen INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE friends(id TEXT PRIMARY KEY,a TEXT NOT NULL,b TEXT NOT NULL,requested_by TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL, accepted_at INTEGER,UNIQUE(a,b));
CREATE TABLE conversations(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('direct','group')),name TEXT NOT NULL DEFAULT '',owner TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE members(conversation TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,uid TEXT NOT NULL,last_read INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(conversation,uid));
CREATE TABLE messages(id TEXT PRIMARY KEY,conversation TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender TEXT NOT NULL,text TEXT NOT NULL DEFAULT '',attachment TEXT,reply_to TEXT,created INTEGER NOT NULL,edited INTEGER,deleted INTEGER NOT NULL DEFAULT 0,pinned INTEGER NOT NULL DEFAULT 0);
CREATE TABLE reactions(message TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,uid TEXT NOT NULL,emoji TEXT NOT NULL,PRIMARY KEY(message,uid,emoji));
CREATE TABLE calls(id TEXT PRIMARY KEY,conversation TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,caller TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL,ended INTEGER);
CREATE TABLE blocks(uid TEXT NOT NULL,target TEXT NOT NULL,PRIMARY KEY(uid,target));
CREATE TABLE bookmarks(uid TEXT NOT NULL,message TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,PRIMARY KEY(uid,message));
CREATE TABLE uploads(id TEXT PRIMARY KEY,owner TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,size INTEGER NOT NULL,created INTEGER NOT NULL,conversation TEXT);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE profiles(uid TEXT PRIMARY KEY REFERENCES users(uid),bio TEXT NOT NULL DEFAULT '',pronouns TEXT NOT NULL DEFAULT '',banner TEXT NOT NULL DEFAULT '#232428');
CREATE TABLE game_collections(uid TEXT NOT NULL,section TEXT NOT NULL,game TEXT NOT NULL,data TEXT NOT NULL,position INTEGER NOT NULL,comment TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',PRIMARY KEY(uid,section,game));
CREATE TABLE servers(id TEXT PRIMARY KEY,name TEXT NOT NULL,icon TEXT NOT NULL DEFAULT '',owner TEXT NOT NULL);
CREATE TABLE server_members(server TEXT NOT NULL REFERENCES servers(id),uid TEXT NOT NULL,PRIMARY KEY(server,uid));
CREATE TABLE movies(id TEXT PRIMARY KEY,owner TEXT NOT NULL,data TEXT NOT NULL,object_key TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE movie_lists(uid TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(uid,id));
CREATE TABLE movie_progress(uid TEXT NOT NULL,id TEXT NOT NULL,position REAL NOT NULL,duration REAL NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(uid,id));
CREATE TABLE movie_rooms(conversation TEXT PRIMARY KEY,state TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated INTEGER NOT NULL);
CREATE TABLE movie_uploads(id TEXT PRIMARY KEY,uid TEXT NOT NULL,upload_id TEXT NOT NULL,object_key TEXT NOT NULL,data TEXT NOT NULL,size INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE expressions(id TEXT PRIMARY KEY,owner TEXT NOT NULL,kind TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,size INTEGER NOT NULL,pack TEXT,created INTEGER NOT NULL);
CREATE TABLE expression_favorites(uid TEXT NOT NULL,kind TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(uid,kind,id));
CREATE TABLE scheduled_messages(id TEXT PRIMARY KEY,conversation TEXT NOT NULL,sender TEXT NOT NULL,text TEXT NOT NULL,reply_to TEXT,deliver_at INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE expression_packs(
 id TEXT PRIMARY KEY,
 name TEXT NOT NULL,
 shared INTEGER NOT NULL DEFAULT 0 CHECK(shared IN (0,1))
);
CREATE TABLE account_options(uid TEXT PRIMARY KEY, data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE profile_extras(uid TEXT PRIMARY KEY, data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE conversation_options(uid TEXT NOT NULL, conversation TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(uid,conversation));
CREATE TABLE hidden_messages(uid TEXT NOT NULL, message TEXT NOT NULL, PRIMARY KEY(uid,message));
CREATE TABLE group_admins(conversation TEXT NOT NULL, uid TEXT NOT NULL, PRIMARY KEY(conversation,uid));
CREATE TABLE chat_uploads(id TEXT PRIMARY KEY, uid TEXT NOT NULL, conversation TEXT NOT NULL, upload_id TEXT NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, size INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE chat_upload_parts(upload TEXT NOT NULL, n INTEGER NOT NULL, etag TEXT NOT NULL, PRIMARY KEY(upload,n));
CREATE TABLE movie_watched(uid TEXT NOT NULL, id TEXT NOT NULL, watched INTEGER NOT NULL, updated INTEGER NOT NULL, PRIMARY KEY(uid,id));
CREATE TABLE movie_captions(id TEXT PRIMARY KEY, movie TEXT NOT NULL, owner TEXT NOT NULL, label TEXT NOT NULL, language TEXT NOT NULL, vtt TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE movie_watch_time(uid TEXT NOT NULL,id TEXT NOT NULL,seconds REAL NOT NULL DEFAULT 0,PRIMARY KEY(uid,id));
CREATE TABLE vela_feature_migrations(id TEXT PRIMARY KEY);
CREATE TABLE read_receipts(uid TEXT NOT NULL,conversation TEXT NOT NULL,last_read INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(uid,conversation));
CREATE TABLE site_admins(uid TEXT PRIMARY KEY,created INTEGER NOT NULL);
CREATE TABLE site_message_rules(id TEXT PRIMARY KEY,data TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,updated_by TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE message_edit_audit(id TEXT PRIMARY KEY,message TEXT NOT NULL,admin TEXT NOT NULL,before_text TEXT NOT NULL,after_text TEXT NOT NULL,edited INTEGER NOT NULL);
CREATE TABLE listening_preferences(uid TEXT PRIMARY KEY,shared INTEGER NOT NULL DEFAULT 0);
CREATE TABLE listening_history(uid TEXT NOT NULL,id TEXT NOT NULL,title TEXT NOT NULL,artist TEXT NOT NULL,album TEXT NOT NULL,started INTEGER NOT NULL,last_seen INTEGER NOT NULL,PRIMARY KEY(uid,id));
CREATE TABLE protected_accounts(uid TEXT PRIMARY KEY);
CREATE TABLE deleted_accounts(uid TEXT PRIMARY KEY,deleted INTEGER NOT NULL,reason TEXT NOT NULL);
CREATE TABLE account_file_cleanup(object_key TEXT PRIMARY KEY);
CREATE TABLE cinema_rooms(conversation TEXT PRIMARY KEY REFERENCES conversations(id) ON DELETE CASCADE,state TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated INTEGER NOT NULL);
