CREATE INDEX friends_a ON friends(a,status);
CREATE INDEX friends_b ON friends(b,status);
CREATE INDEX members_uid ON members(uid,conversation);
CREATE INDEX messages_page ON messages(conversation,created DESC,id DESC);
CREATE INDEX calls_conversation ON calls(conversation,created DESC);
CREATE INDEX scheduled_messages_due ON scheduled_messages(deliver_at);
CREATE INDEX expressions_pack ON expressions(pack,created DESC);
CREATE INDEX messages_live_recent ON messages(conversation,sender,created DESC,id DESC) WHERE deleted=0 AND text LIKE '[[vela-live-music:1:%';
CREATE INDEX messages_live_pinned ON messages(conversation,created DESC,id DESC) WHERE deleted=0 AND pinned=1 AND text LIKE '[[vela-live-music:1:%';
CREATE INDEX messages_live_sender ON messages(sender,conversation,created DESC,id DESC) WHERE deleted=0 AND text LIKE '[[vela-live-music:1:%';
CREATE INDEX calls_active_lookup ON calls(conversation,created DESC) WHERE status IN ('ringing','active');
CREATE INDEX rate_limits_expires ON rate_limits(expires);
CREATE INDEX listening_history_recent ON listening_history(uid,last_seen DESC,id DESC);
CREATE INDEX blocks_target ON blocks(target,uid);
CREATE INDEX users_inactive ON users(last_seen,created);